const { resolveTemplateSyncAction } = require('../theme-utils');

function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

function buildCollectionMap(collections) {
  const map = new Map();

  for (const collection of collections || []) {
    if (collection && collection.handle) {
      map.set(collection.handle, collection.id);
    }
  }

  return map;
}

function buildPublicationIdMap(sourcePublications, destinationPublications, warnings) {
  const destinationByName = new Map(
    (destinationPublications || []).map((publication) => [publication.name, publication.id])
  );
  const publicationIdMap = new Map();

  for (const publication of sourcePublications || []) {
    if (destinationByName.has(publication.name)) {
      publicationIdMap.set(publication.id, destinationByName.get(publication.name));
    } else {
      warnings.push(
        `Source publication "${publication.name}" (ID: ${publication.id}) not found in destination store. It will not be synced for products.`
      );
    }
  }

  return publicationIdMap;
}

function createPairList(sourceIds, destinationIds) {
  return sourceIds.map((sourceId, index) => ({
    sourceId,
    destinationId: destinationIds ? destinationIds[index] : null
  }));
}

async function prepareProductForSync(product, config, client, warnings) {
  const templateAction = await resolveTemplateSyncAction({
    objectType: 'product',
    templateSuffix: product.templateSuffix,
    config,
    client
  });
  warnings.push(...templateAction.warnings);

  if (templateAction.error) {
    throw new Error(templateAction.error);
  }

  return {
    ...product,
    templateSuffix: templateAction.templateSuffix
  };
}

async function syncProducts({ config, client }) {
  const result = makeResult();
  const productsClient = client.source.products;
  const sourceProductIds = productsClient.parseIdList(config.sourceProductIds, {
    allowEmpty: false
  });
  const destinationProductIds = productsClient.parseIdList(
    config.destinationProductIds,
    { allowEmpty: true }
  );
  const isProductIdSync = Boolean(sourceProductIds || destinationProductIds);

  if (config.sourceProductIds && !sourceProductIds) {
    result.errors.push('Source product IDs cannot be empty.');
    result.status = 'failed';
    return result;
  }

  if (config.destinationProductIds && !destinationProductIds) {
    result.errors.push('Destination product IDs are invalid.');
    result.status = 'failed';
    return result;
  }

  if (isProductIdSync && (!sourceProductIds || sourceProductIds.length === 0)) {
    result.errors.push('Product ID sync requires at least one source product ID.');
    result.status = 'failed';
    return result;
  }

  if (
    sourceProductIds &&
    destinationProductIds &&
    destinationProductIds.length !== sourceProductIds.length
  ) {
    result.errors.push('Destination product IDs must match the number of source product IDs.');
    result.status = 'failed';
    return result;
  }

  const destinationCollectionMap = buildCollectionMap(
    await client.destination.collections.listAll()
  );
  const publicationIdMap = buildPublicationIdMap(
    await client.source.products.listPublications(),
    await client.destination.products.listPublications(),
    result.warnings
  );

  let sourceProducts;
  let destinationProducts;

  if (isProductIdSync) {
    sourceProducts = await client.source.products.listByIds(sourceProductIds);

    try {
      const destinationIds = destinationProductIds
        ? destinationProductIds.filter(Boolean)
        : [];
      destinationProducts = await client.destination.products.listByIds(destinationIds);
    } catch (error) {
      destinationProducts = [];
      result.warnings.push(
        'Failed to fetch destination products by ID. Proceeding with an empty destination product list.'
      );
    }

    const sourceById = new Map(sourceProducts.map((product) => [product.id, product]));
    const destinationById = new Map(
      destinationProducts.map((product) => [product.id, product])
    );
    const pairs = createPairList(sourceProductIds, destinationProductIds);

    sourceProducts = [];
    destinationProducts = [];

    for (const pair of pairs) {
      const sourceProduct = sourceById.get(pair.sourceId);
      if (!sourceProduct) {
        result.errors.push(`Source product ID not found: ${pair.sourceId}`);
        result.status = 'failed';
        return result;
      }

      sourceProducts.push(sourceProduct);

      if (pair.destinationId) {
        const destinationProduct = destinationById.get(pair.destinationId);
        if (!destinationProduct) {
          result.errors.push(`Destination product ID not found: ${pair.destinationId}`);
          result.status = 'failed';
          return result;
        }

        destinationProducts.push(destinationProduct);
      }
    }

    const destinationByIdForRun = new Map(
      destinationProducts.map((product) => [product.id, product])
    );

    for (const pair of pairs) {
      const sourceProduct = sourceById.get(pair.sourceId);
      const destinationProduct = pair.destinationId
        ? destinationByIdForRun.get(pair.destinationId)
        : null;

      try {
        const fullSourceProduct = await client.source.products.getFull(sourceProduct.id);
        const preparedProduct = await prepareProductForSync(
          fullSourceProduct,
          config,
          client,
          result.warnings
        );

        if (destinationProduct) {
          if (!config.createOnly) {
            const updated = await client.destination.products.update(
              destinationProduct.id,
              preparedProduct,
              { destinationCollectionMap, publicationIdMap }
            );
            if (updated) {
              result.updated += 1;
            }
          }
        } else if (!config.updateOnly) {
          const created = await client.destination.products.create(preparedProduct, {
            destinationCollectionMap,
            publicationIdMap
          });
          if (created) {
            result.created += 1;
          }
        }
      } catch (error) {
        result.errors.push(`Error processing "${sourceProduct.title}": ${error.message}`);
      }
    }
  } else {
    sourceProducts = await client.source.products.listAll();

    try {
      destinationProducts = await client.destination.products.listAll();
    } catch (error) {
      destinationProducts = [];
      result.warnings.push(
        'Failed to fetch destination products. Proceeding with an empty destination product list.'
      );
    }

    const destinationByHandle = new Map(
      destinationProducts.map((product) => [product.handle, product])
    );

    for (const sourceProduct of sourceProducts) {
      const destinationProduct = destinationByHandle.get(sourceProduct.handle);

      try {
        const fullSourceProduct = await client.source.products.getFull(sourceProduct.id);
        const preparedProduct = await prepareProductForSync(
          fullSourceProduct,
          config,
          client,
          result.warnings
        );

        if (destinationProduct) {
          if (!config.createOnly) {
            const updated = await client.destination.products.update(
              destinationProduct.id,
              preparedProduct,
              { destinationCollectionMap, publicationIdMap }
            );
            if (updated) {
              result.updated += 1;
            }
          }
        } else if (!config.updateOnly) {
          const created = await client.destination.products.create(preparedProduct, {
            destinationCollectionMap,
            publicationIdMap
          });
          if (created) {
            result.created += 1;
          }
        }
      } catch (error) {
        result.errors.push(`Error processing "${sourceProduct.title}": ${error.message}`);
      }
    }

    if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
      const sourceHandles = new Set(sourceProducts.map((product) => product.handle));

      for (const destinationProduct of destinationProducts) {
        if (sourceHandles.has(destinationProduct.handle)) {
          continue;
        }

        try {
          await client.destination.products.delete(destinationProduct.id);
          result.deleted += 1;
        } catch (error) {
          result.errors.push(
            `Error deleting "${destinationProduct.title}": ${error.message}`
          );
        }
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceProducts ? sourceProducts.length : 0,
    destinationCount: destinationProducts ? destinationProducts.length : 0,
    isProductIdSync
  };

  return result;
}

module.exports = {
  syncProducts
};
